// Herd mark - resized (256x256) + base64-embedded from herd-tray/assets/llama-glyph-master.png.
// Kept out of raw HTML to avoid duplicating the blob per usage site; applied via JS to every
// element with data-herd-mark once the shell has rendered.
const HERD_MARK_DATA_URI = "data:image/png;base64,";

function applyHerdMark() {
  document.querySelectorAll('[data-herd-mark]').forEach((img) => {
    img.src = HERD_MARK_DATA_URI;
  });
}
